<div class="toolbar"><button type="button" onclick="window.print()">Imprimir abono</button><a href="{{ route('repair-orders.show',$order) }}">Volver a la orden</a></div>
<article class="sheet"><header class="header"><div><h1>Comprobante de abono</h1><p><strong>{{ $order->company->name }}</strong></p><p>RUT {{ $order->company->formatted_rut ?: 'No informado' }}</p></div><div><p><strong>Orden:</strong> {{ $order->code }}</p><p><strong>Comprobante:</strong> AB-{{ str_pad((string)$payment->id,6,'0',STR_PAD_LEFT) }}</p><p><strong>Fecha:</strong> {{ $payment->payment_date->format('d-m-Y') }}</p></div></header>
<section class="section"><h2>Cliente</h2><div class="grid"><p><strong>Nombre:</strong> {{ $order->client->name }}</p><p><strong>RUT:</strong> {{ $order->client->formatted_rut }}</p><p><strong>Correo:</strong> {{ $order->client->email ?: 'No informado' }}</p><p><strong>Teléfono:</strong> {{ $order->client->phone ?: 'No informado' }}</p></div></section>
<section class="section"><h2>Detalle del abono</h2><table><thead><tr><th>Tipo</th><th>Medio</th><th>Presupuesto</th><th class="money">Monto</th></tr></thead><tbody><tr><td>{{ $payment->payment_type_label }}</td><td>{{ $payment->payment_method_label }}</td><td>{{ $payment->repairQuote?->quote_number ?: 'Orden completa' }}</td><td class="money total">${{ number_format((float)$payment->amount,0,',','.') }}</td></tr></tbody></table>@if($payment->notes)<p><strong>Notas:</strong> {{ $payment->notes }}</p>@endif</section>
<section class="section"><h2>Abonado y pendiente</h2><table><tr><td>Total presupuesto/servicio</td><td class="money">${{ number_format($payment->receiptTotal(),0,',','.') }}</td></tr><tr><td>Total abonado</td><td class="money">${{ number_format($payment->paidThroughThisPayment(),0,',','.') }}</td></tr><tr><td class="total">Saldo pendiente</td><td class="money total">${{ number_format($payment->balanceAfterPayment(),0,',','.') }}</td></tr></table></section>
<footer class="footer">Comprobante generado para la orden {{ $order->code }} · Registrado por {{ $payment->creator?->name ?: 'Sistema' }}</footer></article>
